\set ON_ERROR_STOP on
begin;
create role anon;
create role authenticated;
create role service_role bypassrls;
create schema auth;
create table auth.users(id uuid primary key,email text);
create table public.clients(id uuid primary key default gen_random_uuid(),email text);
create table public.matters(id uuid primary key default gen_random_uuid(),client_id uuid references public.clients(id),name text);
create table public.mio_pnc_workflows(matter_id uuid primary key references public.matters(id),state jsonb default '{}',revision integer default 0,updated_at timestamptz);
create table public.mio_client_intake_requests(id uuid primary key default gen_random_uuid(),matter_id text,recipient_email text,title text,template_snapshot jsonb,status text default 'pending',expires_at timestamptz,submitted_at timestamptz,updated_at timestamptz);
create table public.mio_client_intake_submissions(id uuid primary key default gen_random_uuid(),request_id uuid unique references public.mio_client_intake_requests(id),answers jsonb);
create table public.mio_invoices(id uuid primary key default gen_random_uuid(),user_id uuid,invoice_number text,invoice_type text,matter_id text,client_id text,client_name text,matter_name text,issue_date date,due_date date,status text,total numeric,amount_paid numeric,payment_url text,payment_request_id text,updated_at timestamptz,line_items jsonb);
create table public.lawpay_payment_requests(id uuid primary key default gen_random_uuid(),created_by uuid,matter_id text,matter_name text,client_id text,client_name text,payer_name text,payer_email text,account_key text,amount_cents bigint,invoice_number text,reference text,payment_url text,raw jsonb,gateway_transaction_id text);
create table public.lawpay_transactions(gateway_transaction_id text primary key,status text,reference text,payer_email text,raw jsonb);
\ir ../../supabase/migrations/20261122205113_client_portal_intake_payments.sql
do $test$
declare staff uuid=gen_random_uuid();c1 uuid=gen_random_uuid();c2 uuid=gen_random_uuid();m uuid=gen_random_uuid();inv uuid=gen_random_uuid();form uuid=gen_random_uuid();issued jsonb;first_issue uuid;result jsonb;rid uuid;n integer;threw boolean;
begin
 insert into auth.users values(staff,'staff@example.invalid');
 insert into public.clients values(c1,'client@example.invalid'),(c2,'client@example.invalid');
 insert into public.matters values(m,c1,'Synthetic portal test');
 issued=public.mio_portal_issue_invitation(m,staff,'token-1');first_issue=(issued->>'issuance_id')::uuid;
 issued=public.mio_portal_issue_invitation(m,staff,'token-2');
 perform public.mio_portal_invitation_delivery(m,'client@example.invalid',first_issue,'failed',staff);
 if (select delivery_status from public.mio_portal_grants where matter_id=m)<>'sending' then raise exception 'Stale delivery overwrote current invitation';end if;
 if (select count(*) from public.mio_portal_tokens where matter_id=m and revoked_at is null and used_at is null)<>1 then raise exception 'Multiple live invitation generations';end if;
 result=public.mio_portal_redeem('token-2','synthetic-password-hash',null);
 if (result->>'password_version')::integer<>1 then raise exception 'Session version not bound to redemption';end if;
 threw=false;begin perform public.mio_portal_redeem('token-2','another-hash',null);exception when others then threw=true;end;
 if not threw then raise exception 'Invitation replay accepted';end if;
 update public.matters set client_id=c2 where id=m;
 issued=public.mio_portal_issue_invitation(m,staff,'token-3');
 if (select accepted_at is not null from public.mio_portal_grants where matter_id=m) then raise exception 'Client replacement inherited acceptance';end if;
 perform public.mio_portal_redeem('token-3',null,'client@example.invalid');
 perform public.mio_portal_revoke(m,staff);
 issued=public.mio_portal_issue_invitation(m,staff,'token-4');
 update public.mio_portal_tokens set expires_at=now()-interval '1 minute' where token_hash='token-4';
 threw=false;begin perform public.mio_portal_redeem('token-4',null,'client@example.invalid');exception when others then threw=true;end;
 if not threw then raise exception 'Expired invitation accepted';end if;
 if not public.mio_portal_rate_limit('test-rate',1) or public.mio_portal_rate_limit('test-rate',1) then raise exception 'Rate limiter did not count atomically';end if;
 insert into public.mio_invoices(id,user_id,invoice_number,invoice_type,matter_id,client_id,client_name,matter_name,status,total,amount_paid) values(inv,staff,'INV-1','invoice',m::text,c2::text,'Synthetic','Synthetic','outstanding',100,35);
 result=public.mio_portal_payment_request(inv,'portal:'||inv::text||':6500','https://secure.lawpay.com/pay?amount=65.00','client@example.invalid');rid=(result->>'id')::uuid;
 perform public.mio_portal_payment_request(inv,'portal:'||inv::text||':6500','https://secure.lawpay.com/pay?amount=65.00','client@example.invalid');
 if (select count(*) from public.lawpay_payment_requests where raw->>'invoice_id'=inv::text)<>1 then raise exception 'Duplicate checkout request';end if;
 insert into public.lawpay_transactions values('pending-1','AUTHORIZED','unrelated reference','different@example.invalid',jsonb_build_object('mio_payment_request_id',rid::text));
 if jsonb_array_length(public.mio_portal_pending_payments(inv))<>1 then raise exception 'Canonical pending payment not found';end if;
 threw=false;begin perform public.mio_portal_payment_request(inv,'portal:'||inv::text||':6500','https://secure.lawpay.com/pay?amount=65.00','client@example.invalid');exception when others then threw=true;end;
 if not threw then raise exception 'Pending charge allowed a second checkout';end if;
 insert into public.mio_client_intake_requests(id,matter_id,recipient_email,title,template_snapshot,expires_at) values(form,m::text,'client@example.invalid','Synthetic form','{"questions":[{"key":"name","label":"Name","required":true}]}',now()+interval '1 day');
 threw=false;begin perform public.mio_portal_submit_intake(form,m,'other@example.invalid','{"name":"wrong person"}');exception when others then threw=true;end;
 if not threw then raise exception 'Wrong recipient submitted intake';end if;
 perform public.mio_portal_submit_intake(form,m,'client@example.invalid','{"name":"Synthetic client"}');
 perform public.mio_portal_submit_intake(form,m,'client@example.invalid','{"name":"duplicate"}');
 if (select count(*) from public.mio_client_intake_submissions where request_id=form)<>1 then raise exception 'Duplicate intake submission';end if;
 if has_table_privilege('anon','public.mio_portal_accounts','select') or has_table_privilege('authenticated','public.mio_portal_accounts','select') or has_table_privilege('authenticated','public.mio_portal_mail_tokens','select') then raise exception 'Browser can read portal secrets';end if;
 if has_function_privilege('authenticated','public.mio_portal_redeem(text,text,text)','execute') then raise exception 'Browser can redeem server-only RPC';end if;
 raise notice 'Portal schema behavior verified';
end $test$;
rollback;
